'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
} from 'motion/react';
import { useId, useRef, useState } from 'react';

import { AtSignIcon } from '@/registry/ndeko/lib/icons';
import { MENU_ITEM } from '@/registry/ndeko/lib/recipes';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import {
  draftCommentOf,
  MENTION_TRIGGER,
  segmentsOf,
  type CommentItem,
} from './_parts/comment-model';
import { CommentBlock, PersonAvatar } from './_parts/comment-parts';
import { ENTER, EXIT, heightPresenceOf } from './_parts/motion-parts';
import { CURRENT_USER_ID, PEOPLE, type Person } from './_parts/people';

type MentionQuery = {
  start: number;
  text: string;
};

type TextEdit = {
  value: string;
  caret: number;
};

const MAX_QUERY_LENGTH = 24;

const MAX_SUGGESTIONS = 5;

const FIRST_COMMENTS: CommentItem[] = [
  {
    id: 'm1',
    authorId: 'leo',
    at: '2026-11-05T10:02:00',
    body: 'The column picker is in review. @Tomás Rivera has the dates part.',
  },
];

/** The field and the layer of marks under it share one box and one text setting, or the marks drift off the words. */
const FIELD_BOX =
  'col-start-1 row-start-1 max-h-40 min-h-16 w-full px-3 pt-2.5 pb-1';

const FIELD_TEXT =
  'text-base leading-5 whitespace-pre-wrap [overflow-wrap:anywhere] md:text-[13px]';

const MENTION_MARK =
  'rounded-[3px] bg-primary/15 text-transparent dark:bg-primary/25';

/** Keeps a last empty line drawn in the layer when the text ends with a line break. */
const MIRROR_TAIL = '​';

const POPUP_MOTION: MotionProps = {
  initial: { opacity: 0, scale: 0.95 },
  animate: { opacity: 1, scale: 1 },
  exit: { opacity: 0, scale: 0.95, transition: { ...EXIT, duration: 0.1 } },
  transition: { ...ENTER, duration: 0.15 },
};

const POPUP_FADE: MotionProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: { ...EXIT, duration: 0.1 } },
  transition: { ...ENTER, duration: 0.15 },
};

function popupMotionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return POPUP_FADE;
  }
  return POPUP_MOTION;
}

function startsWord(text: string, index: number) {
  if (index === 0) {
    return true;
  }
  const previous = text.charAt(index - 1);
  return /\s/.test(previous);
}

function mentionQueryBefore(text: string, caret: number) {
  const before = text.slice(0, caret);
  const start = before.lastIndexOf(MENTION_TRIGGER);
  if (start === -1) {
    return null;
  }
  if (!startsWord(text, start)) {
    return null;
  }
  const query = before.slice(start + MENTION_TRIGGER.length);
  const isShortEnough = query.length <= MAX_QUERY_LENGTH;
  const isOneLine = !query.includes('\n');
  const spaceCount = query.split(' ').length - 1;
  const isTwoWordsAtMost = spaceCount <= 1;
  const isQuery = isShortEnough && isOneLine && isTwoWordsAtMost;
  if (!isQuery) {
    return null;
  }
  const mention: MentionQuery = { start, text: query };
  return mention;
}

function matchesQuery(person: Person, query: string) {
  const lowered = query.toLowerCase();
  const name = person.name.toLowerCase();
  if (name.startsWith(lowered)) {
    return true;
  }
  const words = name.split(' ');
  return words.some((word) => word.startsWith(lowered));
}

function suggestionsOf(query: MentionQuery | null) {
  if (!query) {
    return [];
  }
  const others = PEOPLE.filter((person) => person.id !== CURRENT_USER_ID);
  const matching = others.filter((person) => matchesQuery(person, query.text));
  return matching.slice(0, MAX_SUGGESTIONS);
}

function wrappedIndex(index: number, count: number) {
  return (index + count) % count;
}

function triggerFor(text: string, caret: number) {
  if (startsWord(text, caret)) {
    return MENTION_TRIGGER;
  }
  return ` ${MENTION_TRIGGER}`;
}

function insertedAt(text: string, start: number, end: number, insert: string) {
  const value = text.slice(0, start) + insert + text.slice(end);
  const edit: TextEdit = { value, caret: start + insert.length };
  return edit;
}

function MentionLayer({
  text,
  layerRef,
}: {
  text: string;
  layerRef: React.RefObject<HTMLDivElement | null>;
}) {
  const segments = segmentsOf(text);
  return (
    <div
      ref={layerRef}
      aria-hidden='true'
      className={cn(
        FIELD_BOX,
        FIELD_TEXT,
        'pointer-events-none overflow-hidden text-transparent'
      )}
    >
      {segments.map((segment, index) => {
        const key = `${index}-${segment.text}`;
        if (segment.isMention) {
          return (
            <mark key={key} className={MENTION_MARK}>
              {segment.text}
            </mark>
          );
        }
        return <span key={key}>{segment.text}</span>;
      })}
      {MIRROR_TAIL}
    </div>
  );
}

function SuggestionList({
  listId,
  people,
  activeIndex,
  onPick,
  onHighlight,
}: {
  listId: string;
  people: Person[];
  activeIndex: number;
  onPick: (person: Person) => void;
  onHighlight: (index: number) => void;
}) {
  const shouldReduceMotion = useReducedMotion();
  return (
    <motion.div
      id={listId}
      role='listbox'
      aria-label='People to mention'
      {...popupMotionOf(shouldReduceMotion)}
      className='surface-raised absolute bottom-full left-0 z-20 mb-2 w-60 origin-bottom-left rounded-xl p-1'
    >
      {people.map((person, index) => {
        const isActive = index === activeIndex;
        return (
          <div
            key={person.id}
            id={`${listId}-${index}`}
            role='option'
            tabIndex={-1}
            aria-selected={isActive}
            data-highlighted={isActive || undefined}
            onMouseDown={(event) => {
              event.preventDefault();
              onPick(person);
            }}
            onMouseEnter={() => onHighlight(index)}
            className={cn(MENU_ITEM, 'cursor-pointer')}
          >
            <PersonAvatar person={person} className='size-5 text-[9px]' />
            <span className='min-w-0 flex-1 truncate'>{person.name}</span>
          </div>
        );
      })}
    </motion.div>
  );
}

function PostedComment({ comment }: { comment: CommentItem }) {
  const shouldReduceMotion = useReducedMotion();
  return (
    <motion.li
      {...heightPresenceOf(shouldReduceMotion)}
      className='overflow-hidden'
    >
      <CommentBlock comment={comment} className='pb-4' />
    </motion.li>
  );
}

export default function Comment02() {
  const listId = useId();
  const fieldRef = useRef<HTMLTextAreaElement>(null);
  const layerRef = useRef<HTMLDivElement>(null);
  const [comments, setComments] = useState(FIRST_COMMENTS);
  const [body, setBody] = useState('');
  const [query, setQuery] = useState<MentionQuery | null>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const suggestions = suggestionsOf(query);
  const showsSuggestions = suggestions.length > 0;
  const highlighted = Math.min(activeIndex, suggestions.length - 1);
  const trimmed = body.trim();
  const canSend = trimmed.length > 0;
  let activeOptionId: string | undefined;
  if (showsSuggestions) {
    activeOptionId = `${listId}-${highlighted}`;
  }

  function readQuery(text: string, caret: number) {
    setQuery(mentionQueryBefore(text, caret));
    setActiveIndex(0);
  }

  function apply(edit: TextEdit) {
    setBody(edit.value);
    readQuery(edit.value, edit.caret);
    requestAnimationFrame(() => {
      const field = fieldRef.current;
      field?.focus();
      field?.setSelectionRange(edit.caret, edit.caret);
    });
  }

  function caretOf() {
    const field = fieldRef.current;
    if (!field) {
      return body.length;
    }
    return field.selectionStart;
  }

  function pick(person: Person) {
    if (!query) {
      return;
    }
    const mention = `${MENTION_TRIGGER}${person.name} `;
    apply(insertedAt(body, query.start, caretOf(), mention));
  }

  function startMention() {
    const caret = caretOf();
    apply(insertedAt(body, caret, caret, triggerFor(body, caret)));
  }

  function send() {
    if (!canSend) {
      return;
    }
    setComments((current) => [...current, draftCommentOf(trimmed)]);
    setBody('');
    setQuery(null);
  }

  function handleSuggestionKey(
    event: React.KeyboardEvent<HTMLTextAreaElement>
  ) {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setActiveIndex(wrappedIndex(highlighted + 1, suggestions.length));
      return true;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      setActiveIndex(wrappedIndex(highlighted - 1, suggestions.length));
      return true;
    }
    const isPickKey = event.key === 'Enter' || event.key === 'Tab';
    if (isPickKey) {
      event.preventDefault();
      pick(suggestions[highlighted]);
      return true;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      setQuery(null);
      return true;
    }
    return false;
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLTextAreaElement>) {
    if (showsSuggestions) {
      const isHandled = handleSuggestionKey(event);
      if (isHandled) {
        return;
      }
    }
    const isCommand = event.metaKey || event.ctrlKey;
    const isSendKey = isCommand && event.key === 'Enter';
    if (isSendKey) {
      event.preventDefault();
      send();
    }
  }

  function handleChange(event: React.ChangeEvent<HTMLTextAreaElement>) {
    const field = event.target;
    setBody(field.value);
    readQuery(field.value, field.selectionStart);
  }

  function handleSelect(event: React.SyntheticEvent<HTMLTextAreaElement>) {
    const field = event.currentTarget;
    setQuery(mentionQueryBefore(field.value, field.selectionStart));
  }

  function syncLayer(event: React.UIEvent<HTMLTextAreaElement>) {
    const layer = layerRef.current;
    if (layer) {
      layer.scrollTop = event.currentTarget.scrollTop;
    }
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    send();
  }

  return (
    <section aria-label='Comments' className='w-full max-w-md'>
      <ul>
        <AnimatePresence initial={false}>
          {comments.map((comment) => (
            <PostedComment key={comment.id} comment={comment} />
          ))}
        </AnimatePresence>
      </ul>
      <form
        onSubmit={handleSubmit}
        className='bg-card hairline-ring ring-foreground/12 focus-within:ring-ring/25 dark:bg-foreground/[0.04] dark:ring-foreground/15 relative rounded-lg shadow-[0_1px_2px_rgb(0_0_0/0.05)] transition-shadow duration-150 focus-within:ring-[3px]'
      >
        <div className='grid'>
          <MentionLayer text={body} layerRef={layerRef} />
          <textarea
            ref={fieldRef}
            value={body}
            onChange={handleChange}
            onSelect={handleSelect}
            onKeyDown={handleKeyDown}
            onScroll={syncLayer}
            onBlur={() => setQuery(null)}
            rows={2}
            aria-label='Comment, type @ to mention someone'
            aria-autocomplete='list'
            aria-controls={listId}
            aria-activedescendant={activeOptionId}
            placeholder='Comment or type @ to mention someone'
            className={cn(
              FIELD_BOX,
              FIELD_TEXT,
              'placeholder:text-muted-foreground/75 relative resize-none bg-transparent outline-none'
            )}
          />
        </div>
        <div className='flex items-center justify-between px-1.5 pb-1.5'>
          <Button
            type='button'
            variant='ghost'
            size='icon-sm'
            aria-label='Mention someone'
            onClick={startMention}
            className='text-muted-foreground'
          >
            <AtSignIcon />
          </Button>
          <Button type='submit' size='sm' disabled={!canSend}>
            Comment
          </Button>
        </div>
        <AnimatePresence>
          {showsSuggestions && (
            <SuggestionList
              key='suggestions'
              listId={listId}
              people={suggestions}
              activeIndex={highlighted}
              onPick={pick}
              onHighlight={setActiveIndex}
            />
          )}
        </AnimatePresence>
      </form>
    </section>
  );
}

import { CURRENT_USER_ID, PEOPLE } from './people';
import { NOW } from './time';

export type CommentItem = {
  id: string;
  authorId: string;
  at: string;
  body: string;
  editedAt?: string;
};

export type Segment = {
  text: string;
  isMention: boolean;
};

export const MENTION_TRIGGER = '@';

export const MENTION_NAMES = PEOPLE.map((person) => person.name);

function mentionTokensOf(names: string[]) {
  const tokens = names.map((name) => `${MENTION_TRIGGER}${name}`);
  return tokens.sort((first, second) => second.length - first.length);
}

function pushPlain(segments: Segment[], text: string) {
  if (text.length === 0) {
    return;
  }
  segments.push({ text, isMention: false });
}

/** Splits a comment into plain text and mentions of known people, written "@First Last". */
export function segmentsOf(text: string, names: string[] = MENTION_NAMES) {
  const tokens = mentionTokensOf(names);
  const segments: Segment[] = [];
  let plain = '';
  let index = 0;
  while (index < text.length) {
    const token = tokens.find((candidate) => text.startsWith(candidate, index));
    if (token) {
      pushPlain(segments, plain);
      segments.push({ text: token, isMention: true });
      plain = '';
      index += token.length;
      continue;
    }
    plain += text[index];
    index += 1;
  }
  pushPlain(segments, plain);
  return segments;
}

let draftCount = 0;

/** A comment the signed-in person just wrote, stamped with the previews' fixed now. */
export function draftCommentOf(body: string): CommentItem {
  draftCount += 1;
  return {
    id: `draft-${draftCount}`,
    authorId: CURRENT_USER_ID,
    at: NOW,
    body,
  };
}

export function commentWordOf(count: number) {
  if (count === 1) {
    return 'comment';
  }
  return 'comments';
}

export function replyWordOf(count: number) {
  if (count === 1) {
    return 'reply';
  }
  return 'replies';
}

import { cn } from '@/registry/ndeko/lib/utils';
import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import { segmentsOf, type CommentItem } from './comment-model';
import { actorNameOf, personOf, type Person } from './people';
import { relativeTimeOf } from './time';

export const MENTION_CHIP =
  'rounded-[4px] bg-primary/10 px-0.5 font-medium text-primary-ink dark:bg-primary/20';

export const TEXT_ACTION =
  'text-muted-foreground hover:text-foreground focus-visible:ring-ring/25 inline-flex h-6 cursor-pointer items-center gap-1 rounded-md text-xs font-medium transition-colors outline-none focus-visible:ring-[3px]';

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={cn('size-7 text-[10px]', className)}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

/** A comment's words, with each mention of a known person drawn as a tinted chip. */
export function CommentText({
  body,
  className,
}: {
  body: string;
  className?: string;
}) {
  const segments = segmentsOf(body);
  return (
    <p
      className={cn(
        'text-[13px] leading-5 [overflow-wrap:anywhere] whitespace-pre-wrap',
        className
      )}
    >
      {segments.map((segment, index) => {
        const key = `${index}-${segment.text}`;
        if (segment.isMention) {
          return (
            <span key={key} className={MENTION_CHIP}>
              {segment.text}
            </span>
          );
        }
        return <span key={key}>{segment.text}</span>;
      })}
    </p>
  );
}

export function CommentMeta({
  comment,
  children,
}: {
  comment: CommentItem;
  children?: React.ReactNode;
}) {
  return (
    <p className='flex min-w-0 items-baseline gap-1.5 text-[13px]'>
      <span className='truncate font-medium'>
        {actorNameOf(comment.authorId)}
      </span>
      <span aria-hidden='true' className='text-muted-foreground'>
        ·
      </span>
      <time
        dateTime={comment.at}
        className='text-muted-foreground shrink-0 text-xs tabular-nums'
      >
        {relativeTimeOf(comment.at)}
      </time>
      {children}
    </p>
  );
}

type CommentBlockProps = {
  comment: CommentItem;
  avatarClassName?: string;
  meta?: React.ReactNode;
  actions?: React.ReactNode;
  children?: React.ReactNode;
  className?: string;
};

/** Avatar, author and time, then the words aligned under the name. */
export function CommentBlock({
  comment,
  avatarClassName,
  meta,
  actions,
  children,
  className,
}: CommentBlockProps) {
  return (
    <div className={cn('flex gap-3', className)}>
      <PersonAvatar
        person={personOf(comment.authorId)}
        className={avatarClassName}
      />
      <div className='min-w-0 flex-1'>
        <div className='flex min-h-7 items-center justify-between gap-2'>
          <CommentMeta comment={comment}>{meta}</CommentMeta>
          {actions}
        </div>
        {children}
        {!children && <CommentText body={comment.body} />}
      </div>
    </div>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  useReducedMotion,
  type MotionProps,
  type Transition,
  type Variants,
} from 'motion/react';
import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

export const EASE_OUT_STRONG: [number, number, number, number] = [
  0.23, 1, 0.32, 1,
];

export const ENTER: Transition = { duration: 0.2, ease: EASE_OUT_STRONG };

export const EXIT: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

export type PresenceProps = Pick<
  MotionProps,
  'initial' | 'animate' | 'exit' | 'transition'
>;

const HEIGHT_PRESENCE: PresenceProps = {
  initial: { height: 0, opacity: 0 },
  animate: { height: 'auto', opacity: 1 },
  exit: { height: 0, opacity: 0, transition: EXIT },
  transition: ENTER,
};

const FADE_PRESENCE: PresenceProps = {
  initial: { opacity: 0 },
  animate: { opacity: 1 },
  exit: { opacity: 0, transition: EXIT },
  transition: ENTER,
};

/** Rows that arrive or leave a list: their height opens and closes so the rows after them slide. */
export function heightPresenceOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_PRESENCE;
  }
  return HEIGHT_PRESENCE;
}

const SWAP_TRANSITION: Transition = { duration: 0.15, ease: EASE_OUT_STRONG };

const SWAP_VARIANTS: Variants = {
  hidden: { opacity: 0, scale: 0.6, filter: 'blur(2px)' },
  shown: { opacity: 1, scale: 1, filter: 'blur(0px)' },
};

const FADE_VARIANTS: Variants = {
  hidden: { opacity: 0 },
  shown: { opacity: 1 },
};

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

type SwapProps = {
  swapKey: string;
  children: React.ReactNode;
  className?: string;
};

/** An icon or a short label that becomes another one in place. */
export function Swap({ swapKey, children, className }: SwapProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <span className={cn('relative inline-flex', className)}>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={swapKey}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='hidden'
          animate='shown'
          exit='hidden'
          transition={SWAP_TRANSITION}
          className='inline-flex'
        >
          {children}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

const COUNT_SLIDE = 8;

const COUNT_TRANSITION: Transition = { duration: 0.18, ease: EASE_OUT_STRONG };

const COUNT_VARIANTS: Variants = {
  enter: (offset: number) => ({ y: offset, opacity: 0 }),
  center: { y: 0, opacity: 1 },
  leave: (offset: number) => ({ y: -offset, opacity: 0 }),
};

function directionOf(previous: number, next: number) {
  if (next < previous) {
    return -1;
  }
  return 1;
}

function offsetOf(direction: number, shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return 0;
  }
  return direction * COUNT_SLIDE;
}

type RollingCountProps = {
  value: number;
  /** Writes the value, such as a duration; the digits still roll on the number. */
  format?: (value: number) => string;
  className?: string;
};

function plainNumber(value: number) {
  return String(value);
}

/** A figure the person just changed: the new digits slide in from the side of the change. */
export function RollingCount({
  value,
  format = plainNumber,
  className,
}: RollingCountProps) {
  const shouldReduceMotion = useReducedMotion();
  const [previous, setPrevious] = useState(value);
  const [direction, setDirection] = useState(1);

  if (previous !== value) {
    setDirection(directionOf(previous, value));
    setPrevious(value);
  }

  const offset = offsetOf(direction, shouldReduceMotion);

  return (
    <span
      className={cn(
        'relative inline-flex overflow-hidden tabular-nums',
        className
      )}
    >
      <AnimatePresence mode='popLayout' initial={false} custom={offset}>
        <motion.span
          key={value}
          custom={offset}
          variants={COUNT_VARIANTS}
          initial='enter'
          animate='center'
          exit='leave'
          transition={COUNT_TRANSITION}
          className='inline-block'
        >
          {format(value)}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

export type Person = {
  id: string;
  name: string;
  firstName: string;
  initials: string;
  avatar?: string;
};

export const CURRENT_USER_ID = 'amara';

export const PEOPLE: Person[] = [
  {
    id: 'amara',
    name: 'Amara Okafor',
    firstName: 'Amara',
    initials: 'AO',
    avatar: '/avatars/avatar-03.svg',
  },
  {
    id: 'leo',
    name: 'Léo Martin',
    firstName: 'Léo',
    initials: 'LM',
    avatar: '/avatars/avatar-04.svg',
  },
  {
    id: 'sana',
    name: 'Sana Iqbal',
    firstName: 'Sana',
    initials: 'SI',
    avatar: '/avatars/avatar-05.svg',
  },
  {
    id: 'tomas',
    name: 'Tomás Rivera',
    firstName: 'Tomás',
    initials: 'TR',
    avatar: '/avatars/avatar-06.svg',
  },
  {
    id: 'mei',
    name: 'Mei Lin',
    firstName: 'Mei',
    initials: 'ML',
    avatar: '/avatars/avatar-07.svg',
  },
  {
    id: 'jonah',
    name: 'Jonah Brandt',
    firstName: 'Jonah',
    initials: 'JB',
  },
];

export function personOf(id: string) {
  const found = PEOPLE.find((person) => person.id === id);
  if (found) {
    return found;
  }
  return PEOPLE[0];
}

export function isCurrentUser(id: string) {
  return id === CURRENT_USER_ID;
}

export function actorNameOf(id: string) {
  if (isCurrentUser(id)) {
    return 'You';
  }
  return personOf(id).name;
}

export function currentUser() {
  return personOf(CURRENT_USER_ID);
}

import {
  differenceInCalendarDays,
  differenceInMinutes,
  format,
  parseISO,
} from 'date-fns';

/** The previews read every time against one fixed moment, so the server and the browser print the same labels. */
export const NOW = '2026-11-05T11:00:00';

const MINUTES_PER_HOUR = 60;

function daysBeforeNow(iso: string) {
  return differenceInCalendarDays(parseISO(NOW), parseISO(iso));
}

export function relativeTimeOf(iso: string) {
  const minutes = differenceInMinutes(parseISO(NOW), parseISO(iso));
  if (minutes < 1) {
    return 'Just now';
  }
  if (minutes < MINUTES_PER_HOUR) {
    return `${minutes}m ago`;
  }
  const days = daysBeforeNow(iso);
  if (days === 0) {
    const hours = Math.floor(minutes / MINUTES_PER_HOUR);
    return `${hours}h ago`;
  }
  if (days === 1) {
    return 'Yesterday';
  }
  return format(parseISO(iso), 'MMM d');
}

export function exactTimeOf(iso: string) {
  return format(parseISO(iso), "EEE, MMM d 'at' HH:mm");
}

export function clockOf(iso: string) {
  return format(parseISO(iso), 'HH:mm');
}

export function dayKeyOf(iso: string) {
  return iso.slice(0, 10);
}

export function dayLabelOf(iso: string) {
  const days = daysBeforeNow(iso);
  if (days === 0) {
    return 'Today';
  }
  if (days === 1) {
    return 'Yesterday';
  }
  return format(parseISO(iso), 'EEEE, MMM d');
}

export function shortDateOf(iso: string) {
  return format(parseISO(iso), 'MMM d');
}

export function durationLabelOf(minutes: number) {
  const hours = Math.floor(minutes / MINUTES_PER_HOUR);
  const rest = minutes % MINUTES_PER_HOUR;
  if (hours === 0) {
    return `${rest}m`;
  }
  if (rest === 0) {
    return `${hours}h`;
  }
  return `${hours}h ${rest}m`;
}

export function countLabel(count: number, singular: string, plural: string) {
  if (count === 1) {
    return `${count} ${singular}`;
  }
  return `${count} ${plural}`;
}
